Definition goodframe : ltac2:(zQ "20!h9!j4>2lo$0>1v$0>3top$0$1") := ltac2:(zQ "60!h9!jb!la!m0!m6!mf\2lo$0\1v$0\3top$0@2$1@2$1@2$2^3^2@2$2^2@2$5^1+h0@2$3@2$4^2+8Z").

(* [comment removed for export] *)
Fixpoint uloop (pc0 md : Z) (CH : list (Z * Z)) (acc : list Z) {struct CH} : list Z :=
  match CH with
  | [] => acc
  | (ra, v) :: rest =>
      if md <=? Z.of_nat (length acc) then acc
      else if ra <? KPAGE then acc
      else let acc' := if ra =? pc0 then acc else acc ++ [ra] in
           match rest with
           | [] => acc'                      (* [comment removed for export] *)
           | _ => uloop pc0 md rest acc'
           end
  end.

Definition utrace : ltac2:(zQ "30!h9!n5!nc>3pc0$0>2bp$0>3top$0>3bot$0>2md$0>2CH@1$1@2$2$0$0@1$1$0") := ltac2:(zQ "a0!h9!j4!o3!n5!oa!nc!se!t6!u2!la\3pc0$0\2bp$0\3top$0\3bot$0\2md$0\2CH@1$3@2$5$0$0M1\0$1@1$3$0@2$9^4$6@3$2$0^6@1$4$0M1\0$1@1$3$0@3$7^3^5^4@4$8^6^2^1@3$2$0^6@1$4$0@3$2$0^6@1$4$0").

